var CONNECT_TIMEOUT_MS = 1e4;
var log = (...args) => console.error("[camunda-cluster-mcp]", ...args);
if (process.argv.includes("--version")) {
  console.error(VERSION);
  process.exit(0);
}
if (process.argv.includes("--help") || process.argv.includes("-h")) {
  console.error(`camunda-cluster-mcp ${VERSION}

Local MCP server (stdio) for a Camunda 8.9+ Orchestration Cluster. Configure it with the
Camunda SDK environment variables:

  CAMUNDA_REST_ADDRESS         cluster REST address (default http://localhost:8080; /v2 is optional)
  CAMUNDA_AUTH_STRATEGY        NONE | BASIC | OAUTH (inferred from the credentials when unset)
  CAMUNDA_CLIENT_ID / CAMUNDA_CLIENT_SECRET          OAuth client credentials
  CAMUNDA_OAUTH_URL / CAMUNDA_TOKEN_AUDIENCE / CAMUNDA_OAUTH_SCOPE
  CAMUNDA_BASIC_AUTH_USERNAME / CAMUNDA_BASIC_AUTH_PASSWORD

  CAMUNDA_MCP_SERVERS          which cluster servers to use: cluster,processes (default both)
  CAMUNDA_MCP_POLL_SECONDS     how often to re-read the tool list (default 30, 0 = off)
`);
  process.exit(0);
}
var config2 = resolveConfig();
var camunda = createCamundaClient({ config: config2.sdkConfig });
var auth2 = {
  getAuthHeaders: () => camunda.getAuthHeaders(),
  forceAuthRefresh: () => camunda.forceAuthRefresh()
};
var fetchImpl = authFetch(auth2);
var backends = config2.endpoints.map((e) => new Backend(e, fetchImpl, VERSION));
log(`cluster ${config2.baseUrl} (auth ${config2.authStrategy}); servers: ${config2.endpoints.map((e) => e.path).join(", ")}`);
var refreshing;
async function refreshAll() {
  refreshing ??= Promise.all(backends.map((b) => b.refresh())).then(() => {
    for (const b of backends) if (b.state === "error") log(b.lastError);
  }).finally(() => {
    refreshing = void 0;
  });
  return refreshing;
}
await Promise.race([refreshAll(), new Promise((r) => setTimeout(r, CONNECT_TIMEOUT_MS))]);
function instructions() {
  const parts = [
    `Tools for the Camunda 8 cluster at ${config2.baseUrl}. Process tools (from /mcp/processes) appear as processes with an MCP start event are deployed; the list refreshes ${config2.pollSeconds > 0 ? `every ${config2.pollSeconds}s` : "on reconnect"}. If tools are missing or failing, call ${STATUS_TOOL}.`
  ];
  for (const b of backends) if (b.instructions) parts.push(`## ${b.endpoint.path}
${b.instructions.trim()}`);
  return parts.join("\n\n");
}
var statusTool = {
  name: STATUS_TOOL,
  description: "Show how this connector is connected to the Camunda cluster: address, auth strategy, and for each cluster MCP server whether it is reachable, how many tools it offers, and the last error. Use it when Camunda tools are missing or fail.",
  inputSchema: { type: "object", properties: {} },
  annotations: { readOnlyHint: true }
};
function status() {
  return {
    connector: `camunda-cluster-mcp ${VERSION}`,
    cluster: config2.baseUrl,
    auth: config2.authStrategy,
    pollSeconds: config2.pollSeconds,
    servers: backends.map((b) => ({
      path: b.endpoint.path,
      url: b.endpoint.url.toString(),
      state: b.state,
      tools: b.tools.length,
      ...b.serverName ? { server: b.serverName } : {},
      ...b.lastError ? { error: b.lastError } : {}
    }))
  };
}
var server = new Server(
  { name: "camunda-cluster", version: VERSION },
  { capabilities: { tools: { listChanged: true } }, instructions: instructions() }
);
var current = mergeTools(backends);
var lastPrint = fingerprint(current.tools);
server.setRequestHandler("tools/list", async () => {
  await refreshAll();
  current = mergeTools(backends);
  lastPrint = fingerprint(current.tools);
  return { tools: [...current.tools, statusTool] };
});
server.setRequestHandler("tools/call", async (request) => {
  const { name, arguments: args } = request.params;
  if (name === STATUS_TOOL) {
    return { content: [{ type: "text", text: JSON.stringify(status(), null, 2) }] };
  }
  let backend = current.owner.get(name);
  if (!backend) {
    await refreshAll();
    current = mergeTools(backends);
    backend = current.owner.get(name);
  }
  if (!backend) {
    return {
      isError: true,
      content: [{ type: "text", text: `Unknown tool "${name}". It may have been undeployed, or the cluster is unreachable; call ${STATUS_TOOL}.` }]
    };
  }
  try {
    return await backend.callTool(name, args);
  } catch (err) {
    return {
      isError: true,
      content: [{ type: "text", text: `${backend.endpoint.path} failed: ${err instanceof Error ? err.message : String(err)}` }]
    };
  }
});
var initialized = false;
server.oninitialized = () => {
  initialized = true;
};
if (config2.pollSeconds > 0) {
  const timer = setInterval(async () => {
    await refreshAll();
    const next = mergeTools(backends);
    const print = fingerprint(next.tools);
    if (print === lastPrint) return;
    current = next;
    lastPrint = print;
    log(`tool list changed (${next.tools.length} tools)`);
    if (initialized) await server.sendToolListChanged().catch((err) => log("list_changed failed:", err));
  }, config2.pollSeconds * 1e3);
  timer.unref();
}
var shutdown = async () => {
  await Promise.all(backends.map((b) => b.close()));
  process.exit(0);
};
process.stdin.on("end", shutdown);
process.on("SIGINT", shutdown);
process.on("SIGTERM", shutdown);
await server.connect(new StdioServerTransport());
log("ready");
